    for (var i = 0; i < count; i++) {
      AppShell.tab.value = 0;
      await tester.ensureVisible(actions.at(i));
      await tester.pumpAndSettle();
      await tester.tap(actions.at(i));
      await tester.pumpAndSettle();
      expect(AppShell.tab.value, AppShell.explore, reason: '$screen #$i');
    }
